			function onGrdListRowgroupClick( /* cpr.events.CGridMouseEvent */ e) {
			    /** 
			     * @type cpr.controls.Grid
			     */
			    var grdList = e.control;
			    
			    // 실제 클릭된 cellIndex로 column 반환
			    var dmDtlParam = app.lookup("dmDtlParam");
			    var voCol = grdList.getRowGroup("PVSN_RESRCE_NM", "gfooter").getColumn(e.cellIndex);
			    var vcCtrl = voCol.control;
			    
			    if (vcCtrl instanceof cpr.controls.Button) {
			        
			        // 바인딩 컬럼명을 반환받기 위한 colIndex 반환        
			        var vnColIdx = voCol.colIndex;
			        var vsColNm = grdList.detail.getColumn(vnColIdx).columnName;
			        var vnCostSum = e.rowgroup.getSum(vsColNm);
			        
			        if (vnCostSum == 0) return;
			        
			        var instNo = util.DataSet.getValue(app, "dsList", e.rowgroup.startRowIndex, "INST_NO");
			        var resrceNo = util.DataSet.getValue(app, "dsList", e.rowgroup.startRowIndex, "RESRCE_NO");
			        
			        var month = vnColIdx / 2 - 2;
			        if (month < 10)
			            month = '0' + month;
			        var yearMonth = util.DataSet.getValue(app, "dsList", e.rowgroup.startRowIndex, "BIZ_YR") + month;
			        
			        dmDtlParam.setValue("INST_NO", instNo);
			        dmDtlParam.setValue("RESRCE_NO", resrceNo);
			        dmDtlParam.setValue("GIVE_YM", yearMonth);
			        dmDtlParam.setValue("GIVE_AMT", vnCostSum);
			        
			        var initValue = {
			            type: "CREATE",
			            param: dmDtlParam.getDatas()
			        }
			        util.Submit.send(app, "subCheck", function(pbSuccess) {
			            if (pbSuccess) {
			                var msg = app.lookup("subCheck").getMetadata("msg");
			                if (msg == "")
			                    openDetailPopup(initValue);
			                else
			                    util.Msg.alert(app, msg);
			            }
			        });
			    }
			}

